// ── Canvas helpers (module-level to avoid Babel parse limits) ──
const RING_COLORS_CV = ["#1fd4c8","#2e6da4","#4a9fd4","#8b5cf6","#c9a84c","#f97316","#22c55e"];
const VORTEX_COLORS_CV = ["#1fd4c8","#2e6da4","#4a9fd4","#8b5cf6","#c9a84c","#f97316","#22c55e","#e879f9","#f43f5e","#06b6d4"];
const RING_COUNT_CV = 7;

type VortexObj = { angle:number; speed:number; ring:number; color:string; size:number; trail:{x:number;y:number}[]; life:number; born:number };

function cvGetRingDims(i:number, W:number, H:number){ const maxA=W*0.46,minA=W*0.055; const a=minA+(maxA-minA)*(i/(RING_COUNT_CV-1)); return {a,b:a*0.3,cx:W/2,cy:H/2}; }
function cvMakeVortex(ring:number|undefined, t:number, W:number, H:number): VortexObj {
  const r = (ring !== undefined) ? ring : Math.floor(Math.random()*RING_COUNT_CV);
  return { angle:Math.random()*Math.PI*2, speed:(0.009+Math.random()*0.013)*(Math.random()<0.5?1:-1), ring:r, color:VORTEX_COLORS_CV[Math.floor(Math.random()*VORTEX_COLORS_CV.length)], size:3+Math.random()*3, trail:[], life:0, born:t };
}
function cvDrawRings(ctx:CanvasRenderingContext2D, W:number, H:number, t:number, show:boolean){
  if(!show) return;
  for(let i=0;i<RING_COUNT_CV;i++){
    const {a,b,cx,cy}=cvGetRingDims(i,W,H);
    const pulse=0.05+0.02*Math.sin(t*0.4+i*0.8);
    const alpha=Math.floor(pulse*255).toString(16).padStart(2,"0");
    ctx.beginPath(); ctx.ellipse(cx,cy,a,b,0,0,Math.PI*2);
    ctx.strokeStyle=RING_COLORS_CV[i]+alpha; ctx.lineWidth=1; ctx.stroke();
    ctx.fillStyle=RING_COLORS_CV[i]+"33"; ctx.font="9px monospace";
    ctx.fillText("R"+(i+1),cx+a+3,cy+3);
  }
}
function cvDrawVortex(ctx:CanvasRenderingContext2D, v:VortexObj, W:number, H:number){
  const {a,b,cx,cy}=cvGetRingDims(v.ring,W,H);
  const x=cx+Math.cos(v.angle)*a; const y=cy+Math.sin(v.angle)*b;
  v.trail.push({x,y}); if(v.trail.length>32) v.trail.shift();
  for(let i=1;i<v.trail.length;i++){
    const alpha=(i/v.trail.length)*0.45*v.life;
    const aHex=Math.floor(alpha*255).toString(16).padStart(2,"0");
    ctx.beginPath(); ctx.moveTo(v.trail[i-1].x,v.trail[i-1].y); ctx.lineTo(v.trail[i].x,v.trail[i].y);
    ctx.strokeStyle=v.color+aHex; ctx.lineWidth=1.3; ctx.stroke();
  }
  const grd=ctx.createRadialGradient(x,y,0,x,y,v.size*2.5);
  grd.addColorStop(0,v.color+"cc"); grd.addColorStop(1,v.color+"00");
  ctx.beginPath(); ctx.arc(x,y,v.size*2.5,0,Math.PI*2); ctx.fillStyle=grd; ctx.fill();
  ctx.beginPath(); ctx.arc(x,y,v.size*0.5,0,Math.PI*2); ctx.fillStyle="#fff"; ctx.fill();
  return {x,y};
}
function cvCheckInteractions(ctx:CanvasRenderingContext2D, vortices:VortexObj[], W:number, H:number): number {
  let count=0;
  const pos=vortices.map(v=>{ const {a,b,cx,cy}=cvGetRingDims(v.ring,W,H); return {x:cx+Math.cos(v.angle)*a,y:cy+Math.sin(v.angle)*b}; });
  for(let i=0;i<vortices.length;i++){
    for(let j=i+1;j<vortices.length;j++){
      const dx=pos[i].x-pos[j].x,dy=pos[i].y-pos[j].y;
      if(Math.sqrt(dx*dx+dy*dy)<20){
        count++;
        const mx=(pos[i].x+pos[j].x)/2,my=(pos[i].y+pos[j].y)/2;
        const grd=ctx.createRadialGradient(mx,my,0,mx,my,18);
        grd.addColorStop(0,"rgba(255,255,255,0.75)"); grd.addColorStop(1,"rgba(255,255,255,0)");
        ctx.beginPath(); ctx.arc(mx,my,18,0,Math.PI*2); ctx.fillStyle=grd; ctx.fill();
        const sv=vortices[i].speed; vortices[i].speed=vortices[j].speed*0.85; vortices[j].speed=sv*0.85;
      }
    }
  }
  return count;
}
function cvDrawFieldLines(ctx:CanvasRenderingContext2D, vortices:VortexObj[], W:number, H:number){
  const grouped: Record<number,{x:number;y:number;c:string}[]>={};
  vortices.forEach(v=>{ if(!grouped[v.ring]) grouped[v.ring]=[]; const {a,b,cx,cy}=cvGetRingDims(v.ring,W,H); grouped[v.ring].push({x:cx+Math.cos(v.angle)*a,y:cy+Math.sin(v.angle)*b,c:v.color}); });
  Object.values(grouped).forEach(pts=>{ for(let i=0;i<pts.length-1;i++){ ctx.beginPath(); ctx.moveTo(pts[i].x,pts[i].y); ctx.lineTo(pts[i+1].x,pts[i+1].y); ctx.strokeStyle=pts[i].c+"1a"; ctx.lineWidth=0.8; ctx.setLineDash([4,6]); ctx.stroke(); ctx.setLineDash([]); } });
}

